script:
frappe.ui.form.on('Project', {
    refresh(frm) {
        if (!frm.is_new()) {
            frm.add_custom_button(__('Create Work Order'), () => {
                frappe.new_doc('Work Order', { project: frm.doc.name });
            }, __('Actions'));
            frm.add_custom_button(__('Record Site Diary'), () => {
                frappe.new_doc('Site Diary', { project: frm.doc.name });
            }, __('Actions'));
        }
    },
    contract_value(frm) {
        if (!frm.doc.budget_total) {
            frm.set_value('budget_total', frm.doc.contract_value);
        }
    }
});
